  "verdict": "void",
  "section": "15",
  "quote": "A provision in a tenancy agreement providing that all or any part of the remaining rent for a term or any specified period becomes due on default in payment of rent on the due date or on default of any other obligation of the tenant is void.",
  "reason": "Section 15 explicitly invalidates rent acceleration clauses that make future rent for the remainder of a term due upon default of a rent payment or other tenant obligation."
}

